// Fetches the files that sources.json pins and writes each font package's generated face list.
//
//   dotnet run --project tools/FontPack -- fetch      download missing files into sources/ and check every SHA-256
//   dotnet run --project tools/FontPack -- generate   write src/<package>/Faces.g.cs from the fonts, and
//                                                     src/PdfPecker.Hyphenation/Languages.g.cs from sources.json
//   dotnet run --project tools/FontPack -- check      fail if a generated file is not what generate would write
//
// Run from the repository root. The URLs name commits, not branches, and every file is checked against its hash, so a
// changed upstream file cannot reach a package unnoticed; moving to newer fonts changes the URL and the hash together.
using System.Buffers.Binary;
using System.Globalization;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;

string root = Directory.GetCurrentDirectory();
string sourcesDir = Path.Combine(root, "sources");
var manifest = JsonDocument.Parse(File.ReadAllText(Path.Combine(root, "sources.json"))).RootElement;
var entries = new List<(string File, string Package, string Url, string Sha256)>();
var patterns = new List<(string File, string[] Languages, int Left, int Right)>();
foreach (var group in manifest.EnumerateObject())
    foreach (var e in group.Value.EnumerateArray())
    {
        entries.Add((e.GetProperty("file").GetString()!, e.GetProperty("package").GetString()!, e.GetProperty("url").GetString()!, e.GetProperty("sha256").GetString()!));
        if (e.TryGetProperty("languages", out var languages))
            patterns.Add((entries[^1].File, languages.EnumerateArray().Select(l => l.GetString()!).ToArray(), e.GetProperty("left").GetInt32(), e.GetProperty("right").GetInt32()));
    }

switch (args.FirstOrDefault())
{
    case "fetch":
        return await Fetch();
    case "generate":
        return Generate(write: true);
    case "check":
        return Generate(write: false);
    default:
        Console.Error.WriteLine("Usage: dotnet run --project tools/FontPack -- fetch | generate | check");
        return 2;
}

async Task<int> Fetch()
{
    Directory.CreateDirectory(sourcesDir);
    using var http = new HttpClient { Timeout = TimeSpan.FromMinutes(10) };
    int failed = 0;
    foreach (var (file, _, url, sha) in entries)
    {
        string path = Path.Combine(sourcesDir, file);
        if (File.Exists(path) && Hash(File.ReadAllBytes(path)) == sha) continue;
        Console.WriteLine($"Downloading {file}");
        byte[] data;
        try
        {
            data = await http.GetByteArrayAsync(url);
        }
        catch (HttpRequestException ex)
        {
            Console.Error.WriteLine($"{file}: {ex.Message}");
            failed++;
            continue;
        }
        string actual = Hash(data);
        if (actual != sha)
        {
            Console.Error.WriteLine($"{file} has SHA-256 {actual}, not the pinned {sha}.");
            failed++;
            continue;
        }
        await File.WriteAllBytesAsync(path, data);
    }
    return failed == 0 ? 0 : 1;
}

int Generate(bool write)
{
    int stale = 0;
    foreach (var package in entries.Where(e => e.Package.StartsWith("PdfPecker.Fonts.", StringComparison.Ordinal)).GroupBy(e => e.Package))
    {
        var faces = new List<(string File, int Index, string Family, int Weight, bool Italic, string Range)>();
        foreach (var (file, _, _, sha) in package)
        {
            byte[] data = File.ReadAllBytes(Path.Combine(sourcesDir, file));
            if (Hash(data) != sha) throw new InvalidOperationException($"sources/{file} is not the pinned file; run fetch.");
            var offsets = TableDirectories(data);
            for (int i = 0; i < offsets.Count; i++)
            {
                var font = new Sfnt(data, offsets[i]);
                faces.Add((file, i, font.Family, font.Weight, font.Italic, Ranges(font.CodePoints())));
            }
        }
        string text = Render(faces);
        string path = Path.Combine(root, "src", package.Key, "Faces.g.cs");
        if (write)
        {
            File.WriteAllText(path, text);
            Console.WriteLine($"{Path.GetRelativePath(root, path)}: {faces.Count} faces");
        }
        else if (!File.Exists(path) || File.ReadAllText(path) != text)
        {
            Console.Error.WriteLine($"{Path.GetRelativePath(root, path)} is out of date; run generate.");
            stale++;
        }
    }
    if (patterns.Count > 0)
    {
        var sb = new StringBuilder();
        sb.Append("// <auto-generated>\n// tools/FontPack generate wrote this file from sources.json. Do not edit it; run the tool.\n// </auto-generated>\n");
        sb.Append("namespace PdfPecker.FontPacks;\n\n/// <summary>The pattern files, the language tags each one serves and its fewest letters before and after a hyphen.</summary>\ninternal static class Languages\n{\n");
        sb.Append("    public static readonly (string File, string[] Tags, int Left, int Right)[] All =\n    [\n");
        foreach (var (file, languages, left, right) in patterns)
            sb.Append(CultureInfo.InvariantCulture, $"        (\"{file}\", [{string.Join(", ", languages.Select(l => "\"" + l + "\""))}], {left}, {right}),\n");
        sb.Append("    ];\n}\n");
        string path = Path.Combine(root, "src", "PdfPecker.Hyphenation", "Languages.g.cs");
        if (write) File.WriteAllText(path, sb.ToString());
        else if (!File.Exists(path) || File.ReadAllText(path) != sb.ToString())
        {
            Console.Error.WriteLine($"{Path.GetRelativePath(root, path)} is out of date; run generate.");
            stale++;
        }
    }
    return stale == 0 ? 0 : 1;
}

static string Hash(byte[] data) => Convert.ToHexString(SHA256.HashData(data)).ToLowerInvariant();

// The offset of each font's table directory: one for a single font, one per font in a collection.
static List<int> TableDirectories(byte[] d)
{
    if (BinaryPrimitives.ReadUInt32BigEndian(d) != 0x74746366) return new List<int> { 0 }; // 'ttcf'
    int count = (int)BinaryPrimitives.ReadUInt32BigEndian(d.AsSpan(8));
    return Enumerable.Range(0, count).Select(i => (int)BinaryPrimitives.ReadUInt32BigEndian(d.AsSpan(12 + 4 * i))).ToList();
}

// Code points as merged runs in the syntax of CSS unicode-range, without padding: "U+20-7E,U+A0,...".
static string Ranges(SortedSet<int> cps)
{
    var sb = new StringBuilder();
    int? start = null, last = null;
    foreach (int cp in cps.Append(int.MaxValue))
    {
        if (last != null && cp == last + 1) { last = cp; continue; }
        if (start != null)
        {
            if (sb.Length > 0) sb.Append(',');
            sb.Append("U+").Append(start.Value.ToString("X", CultureInfo.InvariantCulture));
            if (last != start) sb.Append('-').Append(last!.Value.ToString("X", CultureInfo.InvariantCulture));
        }
        start = last = cp;
    }
    return sb.ToString();
}

static string Render(List<(string File, int Index, string Family, int Weight, bool Italic, string Range)> faces)
{
    var ranges = faces.Select(f => f.Range).Distinct().ToList();
    var sb = new StringBuilder();
    sb.Append("// <auto-generated>\n// tools/FontPack generate wrote this file from the fonts that sources.json pins. Do not edit it; run the tool.\n// </auto-generated>\n");
    sb.Append("namespace PdfPecker.FontPacks;\n\n/// <summary>The faces of the package's fonts, with the characters each one has.</summary>\ninternal static class Faces\n{\n");
    for (int r = 0; r < ranges.Count; r++)
    {
        sb.Append("    private const string Range").Append(r).Append(" =\n");
        var parts = ranges[r].Split(',');
        var line = new StringBuilder();
        var lines = new List<string>();
        foreach (var p in parts)
        {
            if (line.Length > 0 && line.Length + p.Length + 1 > 100) { lines.Add(line.ToString()); line.Clear(); }
            line.Append(p).Append(',');
        }
        lines.Add(line.ToString().TrimEnd(','));
        sb.Append(string.Join(" +\n", lines.Select(l => "        \"" + l + "\""))).Append(";\n\n");
    }
    sb.Append("    public static readonly Face[] All =\n    [\n");
    foreach (var f in faces)
        sb.Append(CultureInfo.InvariantCulture, $"        new(\"{f.File}\", {f.Index}, \"{f.Family}\", {f.Weight}, {(f.Italic ? "true" : "false")}, Range{ranges.IndexOf(f.Range)}),\n");
    sb.Append("    ];\n}\n");
    return sb.ToString();
}

/// <summary>The little of an OpenType font the face list needs: its family name, weight, style and character map.</summary>
sealed class Sfnt(byte[] d, int directory)
{
    private (int Offset, int Length)? Table(string tag)
    {
        int count = U16(directory + 4);
        uint t = BinaryPrimitives.ReadUInt32BigEndian(Encoding.ASCII.GetBytes(tag));
        for (int i = 0; i < count; i++)
        {
            int rec = directory + 12 + 16 * i;
            if (U32(rec) == t) return ((int)U32(rec + 8), (int)U32(rec + 12));
        }
        return null;
    }

    private int U16(int at) => BinaryPrimitives.ReadUInt16BigEndian(d.AsSpan(at));
    private uint U32(int at) => BinaryPrimitives.ReadUInt32BigEndian(d.AsSpan(at));

    /// <summary>The typographic family (name 16), else the family (name 1), from the Windows English names.</summary>
    public string Family => Name(16) ?? Name(1) ?? throw new InvalidDataException("The font has no family name.");

    public int Weight => U16(Table("OS/2")!.Value.Offset + 4);

    public bool Italic => (U16(Table("OS/2")!.Value.Offset + 62) & 1) != 0;

    private string? Name(int id)
    {
        var (o, _) = Table("name")!.Value;
        int count = U16(o + 2), strings = o + U16(o + 4);
        for (int i = 0; i < count; i++)
        {
            int rec = o + 6 + 12 * i;
            if (U16(rec) == 3 && U16(rec + 2) == 1 && U16(rec + 4) == 0x409 && U16(rec + 6) == id)
                return Encoding.BigEndianUnicode.GetString(d, strings + U16(rec + 10), U16(rec + 8));
        }
        return null;
    }

    /// <summary>The code points of the Unicode cmap subtable: format 12 if there is one, else format 4.</summary>
    public SortedSet<int> CodePoints()
    {
        var (o, _) = Table("cmap")!.Value;
        int count = U16(o + 2);
        int best = -1, bestFormat = 0;
        for (int i = 0; i < count; i++)
        {
            int rec = o + 4 + 8 * i;
            int platform = U16(rec), encoding = U16(rec + 2), sub = o + (int)U32(rec + 4);
            int format = U16(sub);
            bool unicode = platform == 0 || (platform == 3 && encoding is 1 or 10);
            if (unicode && (format == 12 || (format == 4 && bestFormat != 12))) { best = sub; bestFormat = format; }
        }
        var cps = new SortedSet<int>();
        if (bestFormat == 12)
        {
            int groups = (int)U32(best + 12);
            for (int g = 0; g < groups; g++)
            {
                int rec = best + 16 + 12 * g;
                uint first = U32(rec), lastCp = U32(rec + 4), glyph = U32(rec + 8);
                for (uint c = first; c <= lastCp; c++)
                    if (glyph + (c - first) != 0) cps.Add((int)c);
            }
        }
        else if (bestFormat == 4)
        {
            int segs = U16(best + 6) / 2;
            int ends = best + 14, starts = ends + 2 * segs + 2, deltas = starts + 2 * segs, rangeOffsets = deltas + 2 * segs;
            for (int s = 0; s < segs; s++)
            {
                int end = U16(ends + 2 * s), start = U16(starts + 2 * s), delta = U16(deltas + 2 * s), ro = U16(rangeOffsets + 2 * s);
                for (int c = start; c <= end && c != 0xFFFF; c++)
                {
                    int glyph = ro == 0 ? (c + delta) & 0xFFFF : U16(rangeOffsets + 2 * s + ro + 2 * (c - start));
                    if (glyph != 0 && ro != 0) glyph = (glyph + delta) & 0xFFFF;
                    if (glyph != 0) cps.Add(c);
                }
            }
        }
        return cps;
    }
}
